import * as THREE from 'three';
import Birds from "vanta/src/vanta.birds";
import VantaCells from "vanta/src/vanta.cells";


function render_header_animation(elementId) {
    console.log(THREE);
    if (elementId ==="#researchHeader") {
        VantaCells({
            el: elementId,
            mouseControls: true,
            touchControls: true,
            gyroControls: false,
            scale: 1.0,
            color1: 0x2aeb00,
            color2: 0x6e6e2e,
        });
    }else if (elementId ==="#funHeader") {
        Birds({
          el: elementId,
          mouseControls: true,
          touchControls: true,
          gyroControls: false,
          minHeight: 200.00,
          minWidth: 200.00,
          scale: 1.00,
          scaleMobile: 1.00
        });
    }

}

export {render_header_animation};
